UPDATE ICOMPRDT
   SET IV_COLUMN = #{st_gw_url}
     , REF_PR_NO = #{st_legacy_pr_no}
     , ORI_PR_NO = #{st_ori_pr_no}
     , ORI_PR_SEQ = PR_SEQ
     , STATUS = 'R'
     , CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD')
     , CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS') 
 WHERE BUYER = #{st_buyer}
   AND PR_NO = #{sPR_No}
